using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using UsedCarSales.Api.Data; using UsedCarSales.Api.Models;
namespace UsedCarSales.Api.Controllers;
[ApiController, Route("api/[controller]")] public class CarsController(AppDbContext db) : ControllerBase { [HttpGet] public async Task<IActionResult> GetAll([FromQuery]string? search, [FromQuery]string? status) { var q=db.Cars.AsNoTracking().AsQueryable(); if(!string.IsNullOrWhiteSpace(search)) q=q.Where(c=>c.Make.Contains(search)||c.Model.Contains(search)||c.StockNumber.Contains(search)); if(!string.IsNullOrWhiteSpace(status)) q=q.Where(c=>c.Status==status); return Ok(await q.OrderByDescending(c=>c.CreatedAt).ToListAsync()); } [HttpGet("{id:int}")] public async Task<IActionResult> Get(int id) { var car=await db.Cars.FindAsync(id); return car is null?NotFound():Ok(car); } [HttpPost] public async Task<IActionResult> Create(Car car) { car.Id=0; if(string.IsNullOrWhiteSpace(car.StockNumber)) return BadRequest("Stock number is required."); if(await db.Cars.AnyAsync(c=>c.StockNumber==car.StockNumber)) return Conflict("Stock number already exists."); car.Status="Available"; car.CreatedAt=DateTime.UtcNow; db.Cars.Add(car); await db.SaveChangesAsync(); return CreatedAtAction(nameof(Get),new {id=car.Id},car); } [HttpPut("{id:int}")] public async Task<IActionResult> Update(int id, Car input) { var car=await db.Cars.FindAsync(id); if(car is null)return NotFound(); if(car.Status=="Sold") return BadRequest("Sold cars cannot be edited."); car.StockNumber=input.StockNumber; car.Make=input.Make; car.Model=input.Model; car.Year=input.Year; car.OdometerKm=input.OdometerKm; car.FuelType=input.FuelType; car.Transmission=input.Transmission; car.Color=input.Color; car.Price=input.Price; car.ImageUrl=input.ImageUrl; car.Description=input.Description; await db.SaveChangesAsync(); return Ok(car); } [HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id) { var car=await db.Cars.FindAsync(id); if(car is null)return NotFound(); if(car.Status=="Sold")return BadRequest("Sold cars cannot be deleted."); db.Cars.Remove(car); await db.SaveChangesAsync(); return NoContent(); } }
